import numpy as np
def _tree(s):
    rows, stack = [[-1, 0, len(s) + 1, 0]], [0]
    for p, ch in enumerate(s, start=1):
        if ch == '(':
            rows.append([stack[-1], p, 0, 0]); stack.append(len(rows) - 1)
        elif ch == ')':
            rows[stack.pop()][2] = p
        else:
            rows[stack[-1]][3] += 1
    return np.array(rows, dtype=np.int64)
def _code(a):
    a = np.asarray(a)
    if a.shape != (4,):
        return -1.0
    return float(a[0] + a[1] / 100.0 + a[2] / 10000.0 + a[3] / 1000000.0)
assert np.allclose(_code(profile_helix_motifs(_tree('(((((...))((((....))))))).((((...)))).'))), target)

